# @CMD@ shell integration for @SHELL_NAME@.
# Generated by `@CMD@ hook @SHELL@`; safe to load more than once.
# It defines a `@CMD@` function (so `@CMD@ profile use` can change this
# session) and wraps `prompt` to apply directory-bound profiles after `cd`.
# Load it AFTER prompt frameworks (oh-my-posh, starship) that replace `prompt`.

$global:@FN@_bin = @BIN@
$global:@FN@_last = $null
$global:@FN@_indicator = @INDICATOR@
$global:@FN@_color = ($PSVersionTable.PSVersion.Major -ge 7) -or [bool]$env:WT_SESSION -or ($env:TERM_PROGRAM -eq 'vscode') -or ($env:TERM_PROGRAM -eq 'RideShell')
$env:@ENV_SHELL@ = '@SHELL@'

# Tool shims (claude, codex, gh, ...) go first on PATH so they win even over
# tools installed in system-wide PATH directories.
$global:@FN@_shims = @SHIMS@
if (-not (($env:PATH -split [IO.Path]::PathSeparator) -contains $global:@FN@_shims)) {
    $env:PATH = $global:@FN@_shims + [IO.Path]::PathSeparator + $env:PATH
}

function global:@FN@_sync {
    param([switch]$Force, [switch]$Initial)
    $loc = Get-Location
    if ($loc.Provider.Name -ne 'FileSystem') { return }
    $cwd = $loc.ProviderPath
    if (-not $Force -and $cwd -eq $global:@FN@_last) { return }
    $global:@FN@_last = $cwd
    $saved = $global:LASTEXITCODE
    try {
        $extra = @()
        if ($Initial) { $extra = @('--initial') }
        $code = (& $global:@FN@_bin hook-env --shell @SHELL@ --cwd $cwd @extra) -join "`n"
        if ($code.StartsWith('@MARKER@')) { Invoke-Expression $code }
    } catch {
        Write-Warning "@CMD@: $_"
    } finally {
        $global:LASTEXITCODE = $saved
    }
}

function global:@CMD@ {
    if ($args.Count -ge 2 -and $args[0] -eq 'profile' -and $args[1] -eq 'use') {
        $rest = @($args | Select-Object -Skip 2)
        $out = & $global:@FN@_bin profile use @rest --emit @SHELL@
        $status = $LASTEXITCODE
        $text = @($out) -join "`n"
        if ($status -eq 0 -and $text.StartsWith('@MARKER@')) {
            Invoke-Expression $text
        } elseif ($text) {
            $text
        }
        @FN@_sync -Force
        $global:LASTEXITCODE = $status
        return
    }
    & $global:@FN@_bin @args
    $status = $LASTEXITCODE
    @FN@_sync -Force
    $global:LASTEXITCODE = $status
}

if (-not $global:@FN@_original_prompt) {
    $global:@FN@_original_prompt = $function:prompt
    if (-not $global:@FN@_original_prompt) {
        $global:@FN@_original_prompt = { "PS $($executionContext.SessionState.Path.CurrentLocation)$('>' * ($nestedPromptLevel + 1)) " }
    }
}

function global:prompt {
    # Run the original prompt first so it still sees the last command's status.
    $p = & $global:@FN@_original_prompt
    @FN@_sync
    if ($global:@FN@_indicator -and $env:@ENV_ACTIVE@ -and $env:@ENV_PROMPT@ -ne '0') {
        $esc = [char]27
        if ($global:@FN@_color) {
            return "$esc[38;5;111m[$env:@ENV_ACTIVE@]$esc[0m " + $p
        }
        return "[$env:@ENV_ACTIVE@] " + $p
    }
    return $p
}

@FN@_sync -Force -Initial
